async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let state = initial;
  let physicalLine = 0;
  let recordIndex = 0;
  let pending = "";
  let completed = false;

  async function processLine(line) {
    physicalLine++;
    if (line.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex: recordIndex++
    });
    state = result.state;
    return result.done === true;
  }

  async function processText(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        pending += text.slice(start);
        return false;
      }

      const line = pending + text.slice(start, end);
      pending = "";
      if (await processLine(line)) return true;
      start = end + 1;
    }
  }

  try {
    while (true) {
      const step = await iterator.next();
      if (step.done) break;

      const text = decoder.decode(step.value, { stream: true });
      if (await processText(text)) return state;
    }

    if (!(await processText(decoder.decode())) && pending.length > 0) {
      const line = pending;
      pending = "";
      await processLine(line);
    }

    completed = true;
    return state;
  } finally {
    if (!completed) {
      const close = iterator.return;
      if (typeof close === "function") {
        await close.call(iterator);
      }
    }
  }
}
